std::list<int> L;
std::vector<int> V = {3, 2, 1};

// Creates an iterator adaptor specializing insertion
auto it = std::front_inserter(L);

// Direct insertion calls L.push_front(10)
*it = 10; 

// Copies V into L. Each element of V calls L.push_front()
// Resulting order is reversed from V.
std::copy(V.begin(), V.end(), 
          std::front_inserter(L)); 

// Final state of L: {1, 2, 3, 10}
// L.front() is 1. L.back() is 10.
